"""
Final verification summary for the WAL columns clarification.
Run from the flash_sale_engine directory.
"""
import json
import collections
import os

for f in ["logs/coordinator.log", "logs/node_Node-1.log", "logs/node_Node-2.log", "logs/node_Node-3.log"]:
    if os.path.exists(f):
        os.remove(f)

# Import the pipeline freshly so logs are regenerated by the fixed logger.
import sys
sys.path.insert(0, ".")
import src.coordinator
import src.node
import src.ml_allocation

# Re-run the allocation + node initialization so logs exist.
src.ml_allocation.perform_initial_allocation()
import pandas as pd
inv = pd.read_csv("data/inventory_allocated.csv")
nodes = {n: src.node.LocalEngineDataNode(n) for n in inv["node_id"].unique()}
for nid, fr in inv.groupby("node_id"):
    nd = nodes[nid]
    for _, r in fr.iterrows():
        nd.storage.data[r["item_id"]] = int(r["stock_quantity"])

co = src.coordinator.DistributedTransactionCoordinator(nodes)
results = []
for i in range(50):
    results.append(co.execute_flash_sale_transaction(f"TXN-{i:03d}", "ITEM_1000", 1))

print("=== FINAL VERIFICATION SUMMARY ===")
print("committed :", results.count("TRANSACTION_SUCCESS"))
print("aborted   :", results.count("TRANSACTION_ABORTED"))
print("final stock of ITEM_1000:", nodes["Node-1"].storage.read_stock("ITEM_1000"))

co_recs = [json.loads(l) for l in open("logs/coordinator.log") if l.strip()]
node_recs = [json.loads(l) for l in open("logs/node_Node-1.log") if l.strip()]
print()
print("=== node_Node-1.log: COMMIT records ===")
for l in open("logs/node_Node-1.log"):
    r = json.loads(l)
    if r["type"] == "COMMIT":
        print(f"  txn={r['txn_id']:10s} page_id={r['page_id']:10s} undo={r['undo']} redo={r['redo']}")

print()
print("=== node_Node-1.log: ABORT records ===")
for l in open("logs/node_Node-1.log"):
    r = json.loads(l)
    if r["type"] == "ABORT":
        print(f"  txn={r['txn_id']:10s} page_id={r['page_id']:10s} undo={r['undo']} redo={r['redo']}")

print()
print("=== node_Node-1.log: PREPARE_UPDATE records (all) ===")
for l in open("logs/node_Node-1.log"):
    r = json.loads(l)
    if r["type"] == "PREPARE_UPDATE":
        print(f"  txn={r['txn_id']:10s} page_id={r['page_id']:10s} undo={r['undo']:3d} redo={r['redo']:3d}")

print()
print("=== coordinator.log (last 5) ===")
for l in open("logs/coordinator.log").read().splitlines()[-5:]:
    print(" ", l)
